// PayslipPdfLayoutTests.cs
// ─────────────────────────────────────────────────────────────────────────────
// REGRESSION (owner download, production, October 2026, EVT2-0004, Evostel_Test): the payslip PDF
//   1. clipped amounts at the right edge ("SANED (Employee) 93.7", NET PAY "SAR 12,28"),
//   2. let the Earnings amounts run into the Deductions labels,
//   3. had no text layer for the "ti" ligature ("Designaon", "Deducons", "Occupaonal"),
//   4. signed off "Generated by Zayra HRMS" - the product is KynexOne.
//
// What is pinned: every amount is printed COMPLETE and inside the page margin, no two words overlap,
// the extracted text carries the real words (search, copy, screen readers), and the footer says
// KynexOne HRMS. Rendered for the exact owner figures, a stress case (8-digit amounts, 12 earning
// lines, very long labels) and the Arabic / bilingual variant. No database, no network.
//
// Set PAYSLIP_SAMPLE_DIR to also write the rendered PDFs there for a visual check.
// ─────────────────────────────────────────────────────────────────────────────

using FluentAssertions;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using Zayra.Api.Infrastructure.Documents.Letters;
using Zayra.Api.Infrastructure.Payroll;

namespace Zayra.Api.Tests;

public class PayslipPdfLayoutTests
{
    private const double PageMargin = 35;           // LetterService page.Margin(35)
    private const double Tolerance = 0.5;

    private static PayslipData OwnerPayslip(PayslipBrandingConfig? branding = null) => new(
        PayslipNumber: "PS-EVT2-0004-202610", EmployeeCode: "EVT2-0004", EmployeeName: "Test Employee",
        Department: "Operations", Designation: "Operations Coordinator",
        PayYear: 2026, PayMonth: 10, Currency: "SAR",
        Items:
        [
            new PayslipLineItem("Basic Salary", 10_000m, PayslipLineTypes.Earning),
            new PayslipLineItem("Housing allowance", 2_500m, PayslipLineTypes.Earning),
            new PayslipLineItem("Transport allowance", 1_000m, PayslipLineTypes.Earning),
            new PayslipLineItem("GOSI Annuities (Employee)", 1_125m, PayslipLineTypes.Deduction),
            new PayslipLineItem("SANED (Employee)", 93.75m, PayslipLineTypes.Deduction),
            new PayslipLineItem("GOSI Annuities (Employer)", 1_125m, PayslipLineTypes.EmployerContribution),
            new PayslipLineItem("Occupational Hazard (Employer)", 250m, PayslipLineTypes.EmployerContribution),
            new PayslipLineItem("SANED (Employer)", 93.75m, PayslipLineTypes.EmployerContribution),
            new PayslipLineItem("Net Pay", 12_281.25m, PayslipLineTypes.Net),
        ],
        CompanyName: "Evostel Test Company", CompanyNameAr: "شركة إيفوستل للاختبار",
        GeneratedOn: new DateTime(2026, 11, 7, 9, 30, 0, DateTimeKind.Utc),
        Branding: branding);

    /// <summary>Eight-digit amounts, twelve earning lines, labels long enough to wrap.</summary>
    private static PayslipData StressPayslip(PayslipBrandingConfig? branding = null)
    {
        var items = new List<PayslipLineItem>();
        for (var i = 1; i <= 12; i++)
            items.Add(new PayslipLineItem(
                i % 3 == 0
                    ? $"Performance and long-service recognition allowance line {i} (taxable, pro-rated)"
                    : $"Earning line {i}",
                1_234_567.89m, PayslipLineTypes.Earning));
        items.Add(new PayslipLineItem("GOSI Annuities and Occupational Hazard combined contribution (Employee)", 1_234_567.89m, PayslipLineTypes.Deduction));
        items.Add(new PayslipLineItem("بدل سكن وبدل نقل وبدل طبيعة عمل إضافي طويل جدا للاختبار", 1_234_567.89m, PayslipLineTypes.Deduction));
        items.Add(new PayslipLineItem("Occupational Hazard contribution paid by the employer (Employer)", 1_234_567.89m, PayslipLineTypes.EmployerContribution));
        var gross = 12 * 1_234_567.89m;
        items.Add(new PayslipLineItem("Net Pay", gross - 2 * 1_234_567.89m, PayslipLineTypes.Net));
        return new PayslipData(
            "PS-STRESS-202610", "EVT2-0099", "Muhammad Abdulrahman Al-Qahtani Al-Otaibi",
            "Corporate Strategy and Business Transformation Office", "Senior Vice President, Regional Operations",
            2026, 10, "SAR", items,
            "Evostel Telecommunications and Information Technology Company Limited", "شركة إيفوستل للاتصالات وتقنية المعلومات المحدودة",
            new DateTime(2026, 11, 7, 9, 30, 0, DateTimeKind.Utc), branding);
    }

    private static async Task<byte[]> Render(PayslipData data, string sampleName)
    {
        var pdf = await new LetterService().GeneratePayslipPdfAsync(data);
        var dir = Environment.GetEnvironmentVariable("PAYSLIP_SAMPLE_DIR");
        if (!string.IsNullOrWhiteSpace(dir))
        {
            Directory.CreateDirectory(dir);
            await File.WriteAllBytesAsync(Path.Combine(dir, sampleName + ".pdf"), pdf);
        }
        return pdf;
    }

    private static string FullText(byte[] pdf)
    {
        using var doc = PdfDocument.Open(pdf);
        return string.Join("\n", doc.GetPages().Select(p => p.Text));
    }

    /// <summary>The page text with whitespace removed, so wrapped labels still match.</summary>
    private static string Squashed(byte[] pdf) => new string(FullText(pdf).Where(c => !char.IsWhiteSpace(c)).ToArray());

    private static List<Word> Words(byte[] pdf)
    {
        using var doc = PdfDocument.Open(pdf);
        return doc.GetPages().SelectMany(p => p.GetWords()).ToList();
    }

    /// <summary>Every word must sit inside the printable area (page minus the 35pt margin).</summary>
    private static void AssertInsidePrintableArea(byte[] pdf)
    {
        using var doc = PdfDocument.Open(pdf);
        foreach (var page in doc.GetPages())
        {
            var right = page.Width - PageMargin + Tolerance;
            foreach (var w in page.GetWords())
            {
                w.BoundingBox.Right.Should().BeLessThanOrEqualTo(right,
                    $"'{w.Text}' on page {page.Number} runs past the right margin");
                w.BoundingBox.Left.Should().BeGreaterThanOrEqualTo(PageMargin - Tolerance,
                    $"'{w.Text}' on page {page.Number} runs past the left margin");
            }
        }
    }

    /// <summary>An amount (any word with a digit) may not overlap ANY other visible word on its line: the
    /// Earnings amount colliding with the Deductions label is exactly this. Arabic words are compared only
    /// against amounts - PdfPig splits shaped RTL runs into overlapping fragments, which says nothing
    /// about the layout.</summary>
    private static void AssertNoOverlappingWords(byte[] pdf)
    {
        static bool Visible(Word w) => w.Text.Any(ch => !char.IsWhiteSpace(ch) && !char.IsControl(ch)
            && char.GetUnicodeCategory(ch) != System.Globalization.UnicodeCategory.Format);
        using var doc = PdfDocument.Open(pdf);
        foreach (var page in doc.GetPages())
        {
            var words = page.GetWords().Where(Visible).ToList();
            foreach (var amount in words.Where(w => w.Text.Any(char.IsDigit)))
                foreach (var other in words.Where(w => !ReferenceEquals(w, amount)))
                {
                    var a = amount.BoundingBox; var b = other.BoundingBox;
                    var overlapX = Math.Min(a.Right, b.Right) - Math.Max(a.Left, b.Left);
                    var overlapY = Math.Min(a.Top, b.Top) - Math.Max(a.Bottom, b.Bottom);
                    var minHeight = Math.Min(a.Height, b.Height);
                    (overlapX > 1.0 && overlapY > minHeight * 0.5).Should().BeFalse(
                        $"'{amount.Text}' and '{other.Text}' overlap on page {page.Number}");
                }
        }
    }

    // ── 1 + 2: right edge and column collisions ───────────────────────────────────────────────

    [Fact]
    public async Task Payslip_PrintsEveryOwnerAmountComplete()
    {
        var pdf = await Render(OwnerPayslip(), "owner-en");
        var text = FullText(pdf);

        foreach (var amount in new[] { "10,000.00", "2,500.00", "1,000.00", "13,500.00", "1,125.00", "93.75",
                                       "1,218.75", "250.00", "12,281.25" })
            text.Should().Contain(amount, $"the amount {amount} must be printed complete, not clipped");

        // SANED employee and SANED employer: two complete 93.75 figures.
        System.Text.RegularExpressions.Regex.Matches(text, @"93\.75").Count.Should().Be(2);
        text.Should().Contain("SAR 12,281.25", "the NET PAY banner prints the whole figure");
    }

    [Fact]
    public async Task Payslip_KeepsEveryWordInsideThePageMargins()
    {
        AssertInsidePrintableArea(await Render(OwnerPayslip(), "owner-en-margins"));
    }

    [Fact]
    public async Task Payslip_NoWordsOverlap_EarningsAgainstDeductions()
    {
        AssertNoOverlappingWords(await Render(OwnerPayslip(), "owner-en-overlap"));
    }

    [Fact]
    public async Task Payslip_Stress_EightDigitAmountsAndTwelveLines_StayCompleteAndInside()
    {
        var pdf = await Render(StressPayslip(), "stress-en");
        var text = FullText(pdf);

        System.Text.RegularExpressions.Regex.Matches(text, @"1,234,567\.89").Count
            .Should().BeGreaterThanOrEqualTo(12 + 2 + 1, "every stress amount is printed complete");
        text.Should().Contain("SAR " + (10 * 1_234_567.89m).ToString("N2"), "the NET PAY banner prints the whole 8-digit figure");
        AssertInsidePrintableArea(pdf);
        AssertNoOverlappingWords(pdf);
    }

    // ── 3: text layer ─────────────────────────────────────────────────────────────────────────

    [Fact]
    public async Task Payslip_TextLayer_CarriesTheRealWords_NoDroppedLigatures()
    {
        var pdf = await Render(OwnerPayslip(), "owner-en-text");
        var text = FullText(pdf);

        foreach (var word in new[] { "Designation", "Deductions", "Total Deductions", "Occupational Hazard",
                                     "contributions", "Transport allowance", "Annuities", "DEDUCTIONS" })
            text.Should().Contain(word);

        // The tell-tale of the missing "ti" ligature mapping.
        foreach (var broken in new[] { "Designaon", "Annuies", "Deducons", "Occupaonal", "contribuons" })
            text.Should().NotContain(broken);
    }

    // ── 4: branding ───────────────────────────────────────────────────────────────────────────

    [Fact]
    public async Task Payslip_Footer_SaysKynexOneHrms_NotZayra()
    {
        var text = FullText(await Render(OwnerPayslip(), "owner-en-footer"));
        text.Should().Contain("Generated by KynexOne HRMS");
        text.Should().Contain("07 Nov 2026 09:30 UTC");
        text.Should().NotContain("Zayra");
    }

    [Fact]
    public async Task Payslip_Pdf_MetadataNamesKynexOne_NotZayra()
    {
        var pdf = await Render(OwnerPayslip(), "owner-en-meta");
        using var doc = PdfDocument.Open(pdf);
        var info = doc.Information;
        $"{info.Producer} {info.Creator} {info.Title} {info.Author}".Should().NotContain("Zayra");
        info.Creator.Should().Contain("KynexOne");
        info.Producer.Should().Contain("KynexOne");
