    // ── Arabic / bilingual ────────────────────────────────────────────────────────────────────
    // NOTE: the Arabic text layer of the shaped glyphs is not recoverable by an extractor (the embedded
    // Noto subset carries no usable ToUnicode for contextual forms), so Arabic WORDS are pinned by the
    // PayslipArabicTests catalogue tests and by the ABSENCE of the English they replace here; positions
    // and amounts are read from the Latin/numeric words, which extract cleanly.

    private static readonly string[] EnglishLabels =
    {
        "EARNINGS", "DEDUCTIONS", "NET PAY", "Gross Total", "Total Deductions", "Basic Salary",
        "Housing allowance", "Transport allowance", "GOSI Annuities", "SANED", "Occupational Hazard",
        "EMPLOYER CONTRIBUTIONS", "system-generated", "Generated by", "October",
    };

    [Theory]
    [InlineData("ar")]
    [InlineData("bilingual")]
    public async Task ArabicPayslip_PrintsEveryAmountComplete_InsideMargins(string locale)
    {
        var pdf = await Render(OwnerPayslip(new PayslipBrandingConfig(Locale: locale)), $"owner-{locale}");
        var text = FullText(pdf);

        foreach (var amount in new[] { "10,000.00", "2,500.00", "1,000.00", "13,500.00", "1,125.00", "93.75", "1,218.75", "250.00", "12,281.25" })
            text.Should().Contain(amount);
        AssertInsidePrintableArea(pdf);
        AssertNoOverlappingWords(pdf);
    }

    /// <summary>Horizontal extent of an amount, read from its glyphs: in the Arabic variant PdfPig fuses an
    /// amount with the neighbouring Arabic fragment into one "word", so word boxes are not usable there.</summary>
    private static (double Left, double Right) AmountBox(Page page, string amount)
    {
        var letters = page.Letters.ToList();
        for (var i = 0; i < letters.Count; i++)
        {
            var run = new System.Text.StringBuilder(); var j = i;
            while (j < letters.Count && run.Length < amount.Length) run.Append(letters[j++].Value);
            if (run.ToString() == amount)
                return (letters.Skip(i).Take(j - i).Min(l => l.GlyphRectangle.Left), letters.Skip(i).Take(j - i).Max(l => l.GlyphRectangle.Right));
        }
        throw new InvalidOperationException($"'{amount}' is not drawn on the page");
    }

    [Fact]
    public async Task ArabicPayslip_IsMirrored_EarningsOnTheRight_DeductionsOnTheLeft_AmountsAtTheInlineEnd()
    {
        var pdf = await Render(OwnerPayslip(new PayslipBrandingConfig(Locale: "ar")), "owner-ar-mirror");
        using var doc = PdfDocument.Open(pdf);
        var page = doc.GetPage(1);
        var mid = page.Width / 2;

        var earnings = AmountBox(page, "10,000.00");     // first Earnings amount
        var deduction = AmountBox(page, "1,125.00");     // first Deductions amount (employee GOSI)
        var net = AmountBox(page, "12,281.25");

        earnings.Left.Should().BeGreaterThan(deduction.Right, "in the mirrored layout the Earnings table is on the right of the Deductions table");
        deduction.Right.Should().BeLessThan(mid, "Deductions sit in the left half");
        earnings.Left.Should().BeGreaterThan(mid - 1, "Earnings sit in the right half");
        net.Right.Should().BeLessThan(mid, "the NET PAY amount is on the left, its label on the right");
        deduction.Left.Should().BeLessThan(PageMargin + 14, "a Deductions amount starts at the table's left (inline-end) edge");

        // the English layout is the opposite
        using var enDoc = PdfDocument.Open(await Render(OwnerPayslip(), "owner-en-mirror-control"));
        var enPage = enDoc.GetPage(1);
        AmountBox(enPage, "10,000.00").Right.Should().BeLessThan(AmountBox(enPage, "1,125.00").Left);
        AmountBox(enPage, "12,281.25").Left.Should().BeGreaterThan(enPage.Width / 2, "English NET PAY amount is on the right");
    }

    [Fact]
    public async Task ArabicPayslip_HasNoEnglishLabels_NoEnglishDisclaimer_ArabicFooterNamesKynexOne()
    {
        var text = FullText(await Render(OwnerPayslip(new PayslipBrandingConfig(Locale: "ar")), "owner-ar-noenglish"));
        foreach (var english in EnglishLabels)
            text.Should().NotContain(english, $"the Arabic payslip must not print the English '{english}'");
        text.Should().Contain("KynexOne HRMS");
        // the stamp is read back visually reversed in an Arabic paragraph; its parts are all present
        text.Should().Contain("2026").And.Contain("09:30").And.Contain("UTC");
        text.Should().NotContain("Zayra");
    }

    [Fact]
    public async Task ArabicPayslip_ColonAndValue_AreSeparateCells_SoTheColonCannotFlipToTheWrongSide()
    {
        var pdf = await Render(OwnerPayslip(new PayslipBrandingConfig(Locale: "ar")), "owner-ar-fields");
        using var doc = PdfDocument.Open(pdf);
        var page = doc.GetPage(1);
        // The value is a word of its own, not fused with its label into one bidi run...
        page.GetWords().Should().Contain(w => w.Text == "EVT2-0004");
        // ...and the label's colon sits between the value and the label: in a right-to-left row the value is on
        // the left of its label, so the colon is the first mark to the value's right on the same line. (The
        // label text is flush right in its cell, so a few points of cell padding separate colon and value.)
        var value = page.GetWords().First(w => w.Text == "EVT2-0004").BoundingBox;
        bool OnTheLine(UglyToad.PdfPig.Content.Letter l) => Math.Abs(l.GlyphRectangle.Bottom - value.Bottom) < 6;
        var colonsOnTheLine = page.Letters.Where(l => l.Value == ":" && OnTheLine(l)
            && l.GlyphRectangle.Left >= value.Right - 0.5 && l.GlyphRectangle.Left - value.Right < 50).ToList();
        var colonsFlippedToTheValuesLeft = page.Letters.Where(l => l.Value == ":" && OnTheLine(l)
            && l.GlyphRectangle.Right <= value.Left + 0.5 && value.Left - l.GlyphRectangle.Right < 8).ToList();
        colonsFlippedToTheValuesLeft.Should().BeEmpty("a colon directly left of the value is the ':label' flip");
        colonsOnTheLine.Should().NotBeEmpty("the colon follows the value's right edge, ahead of the Arabic label");
    }

    [Fact]
    public async Task BilingualPayslip_PrintsBothLanguages_LeftToRight()
    {
        var pdf = await Render(OwnerPayslip(new PayslipBrandingConfig(Locale: "bilingual")), "owner-bilingual-both");
        var text = FullText(pdf);
        text.Should().Contain("EARNINGS").And.Contain("DEDUCTIONS").And.Contain("NET PAY");
        text.Should().Contain("Basic Salary").And.Contain("GOSI Annuities (Employee)");
        text.Should().Contain("This is a system-generated payslip and is valid without a signature.");
        text.Should().Contain("Generated by KynexOne HRMS");

        using var doc = PdfDocument.Open(pdf);
        var page = doc.GetPage(1);
        AmountBox(page, "10,000.00").Right.Should().BeLessThan(AmountBox(page, "1,125.00").Left, "bilingual keeps the left-to-right layout");
    }

    [Fact]
    public async Task BilingualPayslip_ArabicDisclaimerAndFooterLines_AreRightAligned()
    {
        var pdf = await Render(OwnerPayslip(new PayslipBrandingConfig(Locale: "bilingual")), "owner-bilingual-align");
        using var doc = PdfDocument.Open(pdf);
        var page = doc.GetPage(1);
        var rightEdge = page.Width - PageMargin;

        // The Arabic line sits directly below its English line; its glyphs must reach the right margin.
        foreach (var anchor in new[] { "system-generated", "Generated" })
        {
            var en = page.GetWords().First(w => w.Text == anchor).BoundingBox;
            var below = page.Letters.Where(l => !string.IsNullOrWhiteSpace(l.Value)
                && l.GlyphRectangle.Top < en.Bottom + 1 && l.GlyphRectangle.Bottom > en.Bottom - 16).ToList();
            below.Should().NotBeEmpty($"the Arabic line below '{anchor}'");
            below.Max(l => l.GlyphRectangle.Right).Should().BeGreaterThan(rightEdge - 4,
                $"the Arabic line under '{anchor}' is right-aligned");
        }
    }

    [Fact]
    public async Task ArabicPayslip_Stress_StaysCompleteAndInside()
    {
        var pdf = await Render(StressPayslip(new PayslipBrandingConfig(Locale: "ar")), "stress-ar");
        FullText(pdf).Should().Contain("1,234,567.89");
        AssertInsidePrintableArea(pdf);
        AssertNoOverlappingWords(pdf);
    }
}
